CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('ADMIN','SALES','WAREHOUSE','ACCOUNTS'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE customer_status AS ENUM ('LEAD','ACTIVE','INACTIVE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE customer_type AS ENUM ('RETAIL','WHOLESALE','DISTRIBUTOR'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE challan_status AS ENUM ('DRAFT','CONFIRMED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE movement_type AS ENUM ('IN','OUT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role user_role NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, mobile TEXT NOT NULL, email TEXT, business_name TEXT NOT NULL, gst_number TEXT, type customer_type NOT NULL, address TEXT NOT NULL, status customer_status NOT NULL DEFAULT 'LEAD', follow_up_date DATE, notes TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_followups (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID REFERENCES customers ON DELETE CASCADE, note TEXT NOT NULL, follow_up_date DATE, created_by UUID REFERENCES users, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, sku TEXT UNIQUE NOT NULL, category TEXT NOT NULL, unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price>=0), current_stock INTEGER NOT NULL DEFAULT 0 CHECK (current_stock>=0), min_stock INTEGER NOT NULL DEFAULT 0 CHECK (min_stock>=0), warehouse TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_movements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID REFERENCES products, quantity INTEGER NOT NULL CHECK(quantity>0), movement_type movement_type NOT NULL, reason TEXT NOT NULL, created_by UUID REFERENCES users, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS challans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), challan_number TEXT UNIQUE NOT NULL, customer_id UUID REFERENCES customers, status challan_status NOT NULL DEFAULT 'DRAFT', total_quantity INTEGER NOT NULL DEFAULT 0, created_by UUID REFERENCES users, created_at TIMESTAMPTZ DEFAULT now(), confirmed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS challan_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), challan_id UUID REFERENCES challans ON DELETE CASCADE, product_id UUID REFERENCES products, product_name TEXT NOT NULL, sku TEXT NOT NULL, unit_price NUMERIC(12,2) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0));
CREATE INDEX IF NOT EXISTS customers_search_idx ON customers USING gin (to_tsvector('simple', name || ' ' || business_name));
